        'precision': 0.5,
        'speed': 0.3,
        'attention_to_detail': 0.2,
        'dexterity': 0.2
    }

    # Initialize the total score to zero
    total_score = 0.0

    # Add the weighted scores of each attribute
    for attribute in weights:
        # Evaluate the attribute score. For example, presume 5-point scale.
        attribute_score = getattr(sewing_machine_operator, attribute)

        if attribute == 'age':
            # The older the operator, the higher the score
            if sewing_machine_operator.age == 'young':
                age_score = 1.0
            elif sewing_machine_operator.age == 'middle':
                age_score = 0.75
            elif sewing_machine_operator.age == 'elder':
